DELETE FROM hnd_guard;
PRAGMA defer_foreign_keys = OFF;

CREATE UNIQUE INDEX hnd_recovery_booking_once ON hnd_recovery(json_extract(resolution,'$.outcomeId')) WHERE resolution IS NOT NULL AND json_extract(resolution,'$.outcomeId') IS NOT NULL;
CREATE TABLE hnd_recovery_links (recovery_id TEXT PRIMARY KEY REFERENCES hnd_recovery(id), previous_id TEXT NOT NULL REFERENCES hnd_recovery(id));
CREATE TABLE hnd_recovery_access (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES oa_operators(id), person_version INTEGER NOT NULL,
 number_id TEXT NOT NULL REFERENCES hnd_records(id), capabilities TEXT NOT NULL CHECK(json_valid(capabilities)),
 fallback_id TEXT NOT NULL REFERENCES oa_operators(id), fallback_version INTEGER NOT NULL,
 created_by TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL
);

-- Inbox custody and reviewed messages are separate from call-bound permissions.
CREATE TABLE hnd_message_threads (
 id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES hnd_sources(id),
 business TEXT NOT NULL, peer TEXT NOT NULL, owner_id TEXT, revision INTEGER NOT NULL DEFAULT 1,
 custody TEXT NOT NULL DEFAULT 'handset' CHECK(custody IN ('handset','happytohelp')),
 updated_at INTEGER NOT NULL, UNIQUE(source_id,peer)
);
CREATE TABLE hnd_inbox_messages (
 id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES hnd_message_threads(id),
 provider_sid TEXT NOT NULL, direction TEXT NOT NULL, body TEXT NOT NULL,
 media TEXT NOT NULL CHECK(json_valid(media)), participants TEXT NOT NULL CHECK(json_valid(participants)),
 provider_state TEXT NOT NULL, carrier_state TEXT NOT NULL, occurred_at INTEGER NOT NULL,
 UNIQUE(thread_id,provider_sid)
);
CREATE TABLE hnd_message_history (
 id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES hnd_message_threads(id),
 event TEXT NOT NULL, actor_id TEXT, occurred_at INTEGER NOT NULL
);
CREATE TABLE hnd_message_snippets (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, body TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
 created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE hnd_message_permissions (
 id TEXT PRIMARY KEY, recipient TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose='customer-care'),
 evidence TEXT NOT NULL, approved_by TEXT NOT NULL, owner_version INTEGER NOT NULL,
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);
CREATE TABLE hnd_message_jobs (
 id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES hnd_message_threads(id),
 permission_id TEXT NOT NULL REFERENCES hnd_message_permissions(id), snippet_id TEXT NOT NULL REFERENCES hnd_message_snippets(id),
 body TEXT NOT NULL, media TEXT NOT NULL CHECK(json_valid(media)), due_at INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('draft','queued','sending','accepted','delivered','failed','uncertain','suppressed','canceled')),
 reason TEXT NOT NULL, provider_state TEXT NOT NULL DEFAULT 'not submitted', carrier_state TEXT NOT NULL DEFAULT 'unconfirmed',
 provider_sid TEXT, revision INTEGER NOT NULL DEFAULT 1,
 created_by TEXT NOT NULL, owner_version INTEGER NOT NULL, thread_revision INTEGER NOT NULL,
 policy_id TEXT, approved_at INTEGER, created_at INTEGER NOT NULL,
 UNIQUE(provider_sid)
);
CREATE INDEX hnd_message_jobs_due ON hnd_message_jobs(state,due_at);
CREATE TRIGGER hnd_message_stop AFTER INSERT ON hnd_protection_stops
 WHEN NEW.channel IN ('sms','all') OR NEW.reason='dnc'
 BEGIN
 UPDATE hnd_message_jobs SET state='suppressed',reason='Company-wide STOP or DNC',revision=revision+1
 WHERE state IN ('draft','queued') AND thread_id IN (SELECT id FROM hnd_message_threads WHERE peer=NEW.recipient);
 END;
ALTER TABLE hnd_message_threads ADD COLUMN route_kind TEXT NOT NULL DEFAULT 'programmable';
ALTER TABLE hnd_message_threads ADD COLUMN participants TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(participants));
CREATE TABLE hnd_message_group_routes (
 id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES hnd_sources(id),
 service_sid TEXT NOT NULL, conversation_sid TEXT NOT NULL, approved_by TEXT NOT NULL, owner_version INTEGER NOT NULL,
 created_at INTEGER NOT NULL, revoked_at INTEGER
);
CREATE UNIQUE INDEX hnd_group_route_current ON hnd_message_group_routes(service_sid,conversation_sid) WHERE revoked_at IS NULL;
CREATE TRIGGER hnd_message_history_no_update BEFORE UPDATE ON hnd_message_history BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TRIGGER hnd_message_history_no_delete BEFORE DELETE ON hnd_message_history BEGIN SELECT RAISE(ABORT,'append_only'); END;

-- Reporting assignments are explicit owner-maintained labels, independent of staff teams.
CREATE TABLE hnd_report_groups (
 number TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>0),
 team TEXT NOT NULL CHECK(length(trim(team)) BETWEEN 1 AND 200),
 location TEXT NOT NULL CHECK(length(trim(location)) BETWEEN 1 AND 200),
 actor_id TEXT NOT NULL,
 updated_at INTEGER NOT NULL,
 PRIMARY KEY(number,revision)
);
CREATE TRIGGER hnd_report_groups_no_update BEFORE UPDATE ON hnd_report_groups BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TRIGGER hnd_report_groups_no_delete BEFORE DELETE ON hnd_report_groups BEGIN SELECT RAISE(ABORT,'append_only'); END;

CREATE TABLE hnd_metric_dashboards (
 id TEXT PRIMARY KEY, revision INTEGER NOT NULL, value TEXT NOT NULL,
 updated_by TEXT NOT NULL, updated_at INTEGER NOT NULL
);
ALTER TABLE hnd_metric_schedules ADD COLUMN dashboard_definition TEXT;

CREATE TABLE IF NOT EXISTS agent_door_state (
  id INTEGER PRIMARY KEY CHECK(id=1), envelope TEXT, local_document TEXT,
  local_revision INTEGER NOT NULL DEFAULT 0, local_paused INTEGER NOT NULL DEFAULT 0,
  decision_lock TEXT, decision_until INTEGER
);
CREATE TABLE IF NOT EXISTS agent_door_agents (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, specialist TEXT, sponsor TEXT NOT NULL,
  sponsor_name TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0,
  window INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS agent_door_audit (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, at TEXT NOT NULL,
  agent TEXT NOT NULL, classes TEXT NOT NULL, row TEXT NOT NULL, evidence TEXT
);
CREATE INDEX IF NOT EXISTS agent_door_audit_agent ON agent_door_audit(agent,sequence);
CREATE TABLE IF NOT EXISTS agent_door_calls (
  agent TEXT NOT NULL, key TEXT NOT NULL, digest TEXT NOT NULL, decision_id TEXT NOT NULL,
  created_at INTEGER NOT NULL, state TEXT NOT NULL, outcome TEXT, PRIMARY KEY(agent,key)
);
CREATE TABLE IF NOT EXISTS agent_door_approvals (
  id TEXT PRIMARY KEY, state TEXT NOT NULL, saved TEXT NOT NULL, approvals TEXT NOT NULL DEFAULT '[]',
  result TEXT, version INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS agent_door_reviews (
  id TEXT PRIMARY KEY, state TEXT NOT NULL, saved TEXT NOT NULL, marked_by TEXT, marked_at TEXT
);
CREATE TABLE IF NOT EXISTS agent_door_events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, uri TEXT NOT NULL, event TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS agent_door_events_uri ON agent_door_events(uri,sequence);
CREATE TABLE IF NOT EXISTS agent_door_usage (
  decision_id TEXT PRIMARY KEY, at INTEGER NOT NULL, seed TEXT NOT NULL, specialist TEXT, agent TEXT NOT NULL,
  classes TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS agent_door_usage_day ON agent_door_usage(at);

CREATE TABLE bs_settings (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  rev INTEGER NOT NULL DEFAULT 0,
  document TEXT,
  applied_at TEXT,
  stopped INTEGER NOT NULL DEFAULT 0 CHECK(stopped IN(0,1)),
  token TEXT NOT NULL DEFAULT ''
);
CREATE TABLE bs_overrides (
  field TEXT PRIMARY KEY CHECK(field IN('display_name','owner_name','brand_color','logo','timezone')),
  value TEXT NOT NULL,
  actor TEXT NOT NULL,
  changed_at TEXT NOT NULL
);
CREATE TABLE bs_logo (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  sha256 TEXT NOT NULL,
  type TEXT NOT NULL,
  bytes BLOB NOT NULL
);
CREATE TABLE bs_team (
  email TEXT PRIMARY KEY,
  operator_id TEXT,
  invite INTEGER NOT NULL,
  state TEXT NOT NULL CHECK(state IN('invited','active','inactive','conflict'))
);
CREATE TABLE bs_audit (
  id INTEGER PRIMARY KEY,
  actor TEXT NOT NULL,
  action TEXT NOT NULL,
  field TEXT,
  changed_at TEXT NOT NULL
);
-- An INSERT of NULL fails the transaction if a concurrent write invalidated its fence.
CREATE TABLE bs_assert (value INTEGER NOT NULL);

ALTER TABLE bs_settings ADD COLUMN owner_id TEXT CHECK(owner_id IS NULL OR owner_id <> '');
ALTER TABLE bs_team ADD COLUMN business_id TEXT CHECK(business_id IS NULL OR business_id <> '');
ALTER TABLE bs_team ADD COLUMN business_role TEXT CHECK(business_role IS NULL OR business_role IN('admin','member'));
CREATE UNIQUE INDEX bs_team_business_id ON bs_team(business_id) WHERE business_id IS NOT NULL;
